  ('5f6e1228-a492-4d81-aed5-ac13470fa39a', '20ec10f1-5ebe-45a4-a93f-a428e59e6f8f', 5, 'Os atendentes conhecem bem os produtos e não empurram nada.', now() - interval '84725 minutes'),
