  ('5f6e1228-a492-4d81-aed5-ac13470fa39a', 'ccbb7ad1-5609-49c8-a670-8a1c5749d482', 5, 'Muito profissionais, recomendo de olhos fechados.', now() - interval '114358 minutes'),
  ('5f6e1228-a492-4d81-aed5-ac13470fa39a', 'bf685d80-fa1b-4007-b4c2-93dfad319f95', 5, 'Sempre tem a ração do meu gato, e a entrega é super rápida.', now() - interval '13495 minutes'),
