  ('5f6e1228-a492-4d81-aed5-ac13470fa39a', 'e2a9828a-8e4d-4c52-a411-ec01bafe403f', 5, 'Ótima experiência do início ao fim.', now() - interval '24205 minutes'),
  ('5f6e1228-a492-4d81-aed5-ac13470fa39a', 'e1f70f65-2908-4f3c-8223-3f376e4cc8b9', 5, 'Variedade enorme de rações e brinquedos, e entregaram no mesmo dia.', now() - interval '42984 minutes'),
